def has_close_elements(numbers: List[float], threshold: float) -> bool:
    numbers.sort()
    for i in range(len(numbers) - 1):
        if abs(numbers[i] - numbers[i + 1]) < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = []
    balance = 0

    for char in paren_string.replace(' ', ''):
        if char == '(':
            balance += 1
            current_group.append(char)
        elif char == ')':
            balance -= 1
            current_group.append(char)
            if balance == 0:
                result.append(''.join(current_group))
                current_group = []

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1
    for i in range(n-1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
            break
    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(i1, N):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N or grid[i1][j1] == -1 or grid[i2][j2] == -1:
                    continue
                cur = dp[i1][j1][i2]
                if i1 > 0:
                    cur = max(cur, dp[i1-1][j1][i2])
                if j1 > 0:
                    cur = max(cur, dp[i1][j1-1][i2])
                if i2 > 0:
                    cur = max(cur, dp[i1][j1][i2-1])
                if j2 > 0 and i1 != i2:
                    cur = max(cur, dp[i1][j1][i2][j2-1])
                if cur == -float('inf'):
                    continue
                cur += grid[i1][j1]
                if i1 != i2:
                    cur += grid[i2][j2]
                dp[i1][j1][i2] = cur

    return max(0, dp[N-1][N-1][N-1])

