def cantor_numbering(N: int) -> str:
    level = 1
    while N > level:
        N -= level
        level += 1
    if level % 2 == 0:
        return f"{N}/{level - N + 1}"
    else:
        return f"{level - N + 1}/{N}"

def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_product = 0
        for i in range(start + 1, N - k + 1):
            current_product = int(num_str[start:i]) * helper(i, k - 1)
            max_product = max(max_product, current_product)
        return max_product

    return helper(0, K)

