def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        total = 0
        for i, char in enumerate(isbn.replace('-', '')):
            if char == 'X':
                value = 10
            else:
                value = int(char)
            total += value * (10 - i)
        checksum = 11 - (total % 11)
        return 'X' if checksum == 10 else str(checksum % 11)

    clean_isbn = isbn.replace('-', '')
    expected_checksum = calculate_checksum(isbn[:-1] + '0')
    if clean_isbn[-1] == expected_checksum:
        return "Right"
    else:
        correct_isbn = isbn[:-1] + expected_checksum
        return f"{correct_isbn[0]}-{correct_isbn[1:4]}-{correct_isbn[4:9]}-{correct_isbn[9]}"

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    horizontal_counts = [0] * (M - 1)
    vertical_counts = [0] * (N - 1)

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:
            # Same row, vertical aisle can separate them
            if Yi < Qi:
                vertical_counts[Yi - 1] += 1
            else:
                vertical_counts[Qi - 1] += 1
        elif Yi == Qi:
            # Same column, horizontal aisle can separate them
            if Xi < Pi:
                horizontal_counts[Xi - 1] += 1
            else:
                horizontal_counts[Pi - 1] += 1

    # Select K most effective horizontal aisles
    horizontal_aisles = sorted(range(M - 1), key=lambda x: horizontal_counts[x], reverse=True)[:K]
    # Select L most effective vertical aisles
    vertical_aisles = sorted(range(N - 1), key=lambda x: vertical_counts[x], reverse=True)[:L]

    return (' '.join(map(str, sorted(horizontal_aisles + [M]))), ' '.join(map(str, sorted(vertical_aisles + [N]))))

def count_passing_ways(n: int, m: int) -> int:
    if n % 2 == 1 and m % 2 == 0:
        return 0
    if n % 2 == 0 and m % 2 == 1:
        return 0

    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0]

