def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    dp = [0] * (n + 1)
    for price, importance in items:
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + price * importance)
    return max(dp)

def max_energy(beads):
    n = len(beads)
    beads = [0] + beads + [0]  # Add dummy values to handle circular nature
    dp = [[0] * (n + 2) for _ in range(n + 2)]

    for length in range(2, n + 2):
        for i in range(1, n + 2 - length):
            j = i + length - 1
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[1][n + 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else '+'
        if i == 0:
            sign = ''  # No leading '+' sign
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        if degree == 0:
            term = f'{sign}{coeff_str}'
        elif degree == 1:
            term = f'{sign}{coeff_str}x'
        else:
            term = f'{sign}{coeff_str}x^{degree}'
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for m in message:
        if m in mapping:
            decoded_message.append(mapping[m])
        else:
            return "Failed"

    return ''.join(decoded_message)

def largest_prime_factor(n: int) -> int:
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0
    count = 0
    for i in range(x, n - k * x + 1):
        count += count_partitions(n - i, k - 1, i)
    return count

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    if last == 1:
        return 1
    count = 1  # Include the sequence with only the starting number
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd

    count = 0
    target = y0 // x0

    for a in range(1, int(target**0.5) + 1):
        if target % a == 0:
            b = target // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, target in rules:
            start = 0
            while start < len(current):
                pos = current.find(src, start)
                if pos == -1:
                    break
                new_string = current[:pos] + target + current[pos+len(src):]
                if new_string == B:
                    return steps + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))
                start = pos + 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, set

    # Convert the number to a string for easier manipulation
    original_number = str(n)
    # Create a set to store unique numbers
    unique_numbers = set([original_number])
    # Create a queue for BFS and initialize it with the original number
    queue = deque([original_number])

    # Create a dictionary to store the transformation rules for quick lookup
    transformation_dict = {}
    for x, y in rules:
        if x not in transformation_dict:
            transformation_dict[x] = set()
        transformation_dict[x].add(y)

    # Perform BFS
    while queue:
        current_number = queue.popleft()
        for i in range(len(current_number)):
            digit = int(current_number[i])
            if digit in transformation_dict:
                for transformed_digit in transformation_dict[digit]:
                    new_number = current_number[:i] + str(transformed_digit) + current_number[i+1:]
                    if new_number not in unique_numbers:
                        unique_numbers.add(new_number)
                        queue.append(new_number)

    # Return the count of unique numbers
    return len(unique_numbers)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for speaker, stmts in statements.items():
        for stmt in stmts:
            if any(day in stmt for day in days_of_week):
                continue  # Ignore statements about the day of the week
            if speaker in liar_count:
                # If the speaker is a liar, their statement should be false
                if scenario in stmt and "not guilty" in stmt:
                    return False
                if scenario not in stmt and "guilty" in stmt:
                    return False
            else:
                # If the speaker is not a liar, their statement should be true
                if scenario in stmt and "guilty" not in stmt:
                    return False
                if scenario not in stmt and "not guilty" not in stmt:
                    return False
    return True

