def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)
    for volume in volumes:
        for w in range(V, volume - 1, -1):
            dp[w] = max(dp[w], dp[w - volume] + volume)
    return V - dp[V]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if c.islower():
            start = ord('a')
        else:
            start = ord('A')
        return chr(start + (ord(c) - start - (ord(k) - ord('A'))) % 26)

    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]
    plaintext = ''

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        plaintext += chr(value + 65) if ciphertext[i].isupper() else chr(value + 97)

    return plaintext.lower()

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    unhappy_day = 0
    for i, (school_hours, extra_hours) in enumerate(schedule, start=1):
        total_hours = school_hours + extra_hours
        if total_hours > 8:
