def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    left_max = [1] * n
    right_max = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_max[i] = left_max[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_max[i] = right_max[i + 1] + 1

    min_students = n
    for i in range(n):
        min_students = min(min_students, n - (left_max[i] + right_max[i] - 1))

    return min_students

def min_groups(w, n, prices):
    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    moves = 2
    for i in range(1, n):
        moves = 3 * moves + 2
    return moves
